function UIBattlingTrainingTargetPanel:ShowConditionDesc()
    Events.Broadcast(Constants.EventNames.BattleShowLevelTips, 3)
    self.siBtnBG.Status = 2
    KTool.SetActive(self.Root_MissionDesc, true)
    local state = self:PlayRootDesc(PATH_AUTO_SHOW, function()
        KTool.SetActive(self.Btn_CloseDesc.gameObject, true)
        self.isShowDesc = true
        KTool.SetActive(self.InfoPanel3.gameObject, false)
    end)
    return state
end

function UIBattlingTrainingTargetPanel:HideConditionDesc()
    self:CleanCoShowPanel()
    KTool.SetActive(self.Btn_CloseDesc.gameObject, false)
    self.siBtnBG.Status = 1
    local state = self:PlayRootDesc(PATH_HIDE, function()
        if self.isStarQuest then
            KTool.SetActive(self.InfoPanel3.gameObject, true)
        end
        self.isShowDesc = false
        KTool.SetActive(self.Root_MissionDesc, false)
    end)
    return state
end

function UIBattlingTrainingTargetPanel:SetShowState(state)
    self.isShowDesc = state
    self.siBtnBG.Status = state and 2 or 1
    KTool.SetActive(self.Btn_CloseDesc.gameObject, state)
    KTool.SetActive(self.InfoPanel3.gameObject, not state)
    KTool.SetActive(self.Root_MissionDesc, state)
end

function UIBattlingTrainingTargetPanel:RemoveListener()
    Events.RemoveListener(Constants.EventNames.BattleMissionUpdated, self.eventUpdateConditionValue)
    -- Events.RemoveListener(Constants.EventNames.BattleRequireInput, self.eventBattleRequireInput)
end

