function UIBattlingTrainingTargetPanel:InitStarsSign(missionData)
    local arrayImage = self.InfoPanel3:GetComponentsInChildren(typeof(Image), true)
    for i = 1, arrayImage.Length do
        local index = i - 1
        table.insert(self.listStarsImg, {img = arrayImage[index], type = 0})
    end
    if missionData and self.listStarsImg then
        for i, data in ipairs(missionData) do
            local id = data.id
            self.listStarsImg[i].type = id
        end
    end
    KTool.SetActive(self.InfoPanel3.gameObject, true)
end

function UIBattlingTrainingTargetPanel:CleanCoShowPanel()
    if self.coShowPanel then
        cs_coroutine.stop(self.coShowPanel)
        self.coShowPanel = nil
    end
end 

function UIBattlingTrainingTargetPanel:CleanCoAutoShow()
    if self.coAutoShow then
        cs_coroutine.stop(self.coAutoShow)
        self.coAutoShow = nil
    end
end

function UIBattlingTrainingTargetPanel:CleanCoAutoHide()
    if self.coAutoHideBattleStart then
        cs_coroutine.stop(self.coAutoHideBattleStart)
        self.coAutoHideBattleStart = nil
    end
end

function UIBattlingTrainingTargetPanel:CleanAnimatorCo()
    self:CleanCoAutoHide()
    self:CleanCoShowPanel()
    self:CleanCoAutoShow()
end

function UIBattlingTrainingTargetPanel:PlayRootDesc(name, cb)
    xTry(function()
        if not isNull(self.Anim_InfoPanel) then
            local state = self.Anim_InfoPanel:TryPlay(checkString(name))
            state.Time = 0
            state.Events:SetEndAction(cb)
            return state
        end
    end)
end

function UIBattlingTrainingTargetPanel:PlayPanelAutoShow(cb)
    -- print("->UIBattlingTrainingTargetPanel:PlayPanelAutoShow")
    self:CleanAnimatorCo()
    self.coAutoShow = cs_coroutine.start(function()
        if not IsNull(self.Anim_InfoPanel) then
            self.siBtnBG.Status = 2
            KTool.SetActive(self.Root_MissionDesc, true)
            local state = self:PlayRootDesc(PATH_AUTO_SHOW)
            cs_coroutine.yield_return(state)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(3))
            if not isNull(self.Anim_InfoPanel) then
                state = self.Anim_InfoPanel:TryPlay(PATH_HIDE)
                cs_coroutine.yield_return(state)
            end
            cb()
            self.coAutoShow = nil
        else
            cb()
        end
    end)
end

function UIBattlingTrainingTargetPanel:CheckTypeId(id)
    for i, _id in pairs(self.listIdsFinish) do
        if id == _id then
            return true
        end
    end
    return false
end

---UpdateConditionValue
---更新任务进度
---@param index number 任务序号
---@param value number 任务进度值
function UIBattlingTrainingTargetPanel:UpdateConditionValue(data)
    -- print("->UIBattlingTrainingTargetPanel:UpdateConditionValue", table.dump(data)) --todo 打印逻辑数据
    local index = data.type -- 任务序号
    local value = data.value -- 任务完成度
    local state = checkNumber(data.state) -- 任务完成状态
    local isFinish = (state == Constants.BattleConditionState.Succeed)
    if isNull(self.listNodeCondition)  then return end
    for i, cell in pairs(self.listNodeCondition) do
        cell:UpdateCell(index, value, state)
        if isFinish then 
            local inList = self:CheckTypeId(index)
            if (not inList) and (not self.isShowDesc) then
                self:PlayPanelAutoShow(function()
                    KTool.SetActive(self.Btn_CloseDesc.gameObject, false)
                    self.siBtnBG.Status = 1
                    self.isShowDesc = false
                end)
                table.insert(self.listIdsFinish, index)
            end
        end
    end
    for i, imgData in pairs(self.listStarsImg) do
        if isFinish and index == imgData.type then
            imgData.img.enabled = true
        end
    end
    local missionState = true
    for i = 1, #self.listNodeCondition do
        local nodeTaskState = self.listNodeCondition[i].isFinish
        missionState = missionState and nodeTaskState
    end
    if missionState then
        self.siBtnBG.Status = 3
        if not self.isShowDesc then
            KTool.SetActive(self.InfoPanel2.gameObject, true)
        end
        if not self.isStarQuest then
            -- UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattlingTrainingTargetFinishDialog })
        end
        -- print("_____本场战斗任务完成")
    end
end

function UIBattlingTrainingTargetPanel:CleanNode()
    if self.listNodeCondition then
        for i = #self.listNodeCondition, 1, -1 do
            local goNode = self.listNodeCondition[i].controller.gameObject
            KTool.SafeDelete(goNode)
        end
        self.listNodeCondition = nil
    end
    self.listNodeCondition = {}
end

function UIBattlingTrainingTargetPanel:UpdateNodeList(data)
    if isNull(self.listNodeCondition) then self.listNodeCondition = {} end
    local group = data.group
    for i = 1, #self.listNodeCondition do
        local node = self.listNodeCondition[i]
        local isInit = node.isInit
        local _group = node.group
        if isInit and _group == group then
            node:UpdateCondition(data)
            return
        end
    end
    self:InitTargetNode(data)
end

function UIBattlingTrainingTargetPanel:InitTargetNode(data)
    local goNode = GameObject.Instantiate(self.TargetInfoOrNode.gameObject, self.Root_FatherTargetDesc)
    if not IsNull(goNode) then
        KTool.SetActive(goNode, true)
        local lbNodeMissionDesc = GetLuaBehaviour(goNode, Constants.UIBattlingLuaTablePath.UIBattlingTrainingTargetCell)
        if not IsNull(lbNodeMissionDesc) then
            lbNodeMissionDesc:Init()
            local ltNodeMissionDesc = lbNodeMissionDesc.Env -- targetNode 的 luaTable
            if ltNodeMissionDesc then
                ltNodeMissionDesc:UpdateCondition(data)
                table.insert(self.listNodeCondition, ltNodeMissionDesc)
            end
        end
    end
end

